import { installNativeTransport, NativeBridgeError, validateNativeHostInfo, type EventSubscription, type NativeHostInfo, type NativeTransport } from "./nativeBridge.ts";

/** Shapes generated by bay.mojom.NativeHost, without importing Mojo into shared code. */
export interface MojoNativeHostRemote {
  getHostInfo(): Promise<{ infoJson: string }>;
  invoke(module: string, method: string, argsJson: string): Promise<{ resultJson: string }>;
  setClient(client: unknown): void;
  $?: { close?(): void };
}
type RouterEvent<Args extends unknown[]> = { addListener(listener: (...args: Args) => void): number };
export interface MojoNativeHostClientRouter {
  onNativeEvent: RouterEvent<[module: string, name: string, payloadJson: string]>;
  onHostInfoChanged: RouterEvent<[infoJson: string]>;
  removeListener(id: number): boolean | void;
  $: { bindNewPipeAndPassRemote(): unknown; close?(): void };
}
export type WebNativeBridgeOptions = {
  remote: MojoNativeHostRemote;
  client: MojoNativeHostClientRouter;
  onProtocolError?: (error: Error) => void;
  bootstrapTimeoutMs?: number;
};

/** Only the trusted chrome://bay bootstrap creates the Mojo endpoints. No window messages are accepted. */
export async function createMojoTransport({ remote, client, onProtocolError = error => console.error(error), bootstrapTimeoutMs = 15000 }: WebNativeBridgeOptions): Promise<NativeTransport> {
  let info: NativeHostInfo | null = null;
  let failure: Error | null = null;
  let disposed = false;
  const listeners = new Map<string, Map<string, Set<{ listener: (payload: unknown) => void }>>>();
  const removers: number[] = [];
  const parseInfo = (json: string): NativeHostInfo => {
    const parsed: unknown = JSON.parse(json);
    validateNativeHostInfo(parsed);
    return parsed;
  };
  const active = () => {
    if (disposed) throw new NativeBridgeError("transport_closed", "Bay's native transport is closed");
    if (failure) throw failure;
  };
  const dispose = () => {
    if (disposed) return;
    disposed = true;
    for (const id of removers) client.removeListener(id);
    listeners.clear();
    client.$.close?.();
    remote.$?.close?.();
  };
  try {
    removers.push(client.onHostInfoChanged.addListener(json => {
      if (disposed) return;
      try { info = parseInfo(json); }
      catch (error) {
        failure = error instanceof Error ? error : new Error(String(error));
        onProtocolError(failure);
      }
    }));
    removers.push(client.onNativeEvent.addListener((module, event, json) => {
      if (disposed || failure) return;
      let payload: unknown;
      try { payload = JSON.parse(json); }
      catch { onProtocolError(new NativeBridgeError("invalid_event", `Invalid native event JSON for ${module}.${event}`)); return; }
      for (const subscription of [...(listeners.get(module)?.get(event) ?? [])]) subscription.listener(payload);
    }));
    remote.setClient(client.$.bindNewPipeAndPassRemote());
    let timeout: ReturnType<typeof setTimeout> | undefined;
    let initial: NativeHostInfo;
    try {
      const response = await Promise.race([
        remote.getHostInfo(),
        new Promise<never>((_, reject) => {
          timeout = setTimeout(() => reject(new NativeBridgeError("bootstrap_timeout", "Bay's native host did not finish starting")), bootstrapTimeoutMs);
        }),
      ]);
      initial = parseInfo(response.infoJson);
    } finally { clearTimeout(timeout); }
    active();
    // An update received during bootstrap is newer than the initial request's snapshot.
    info ??= initial;
    return {
      getHostInfo() { active(); return info!; },
      async invoke(module, method, argsJson) {
        active();
        const result = await remote.invoke(module, method, argsJson);
        active();
        return result.resultJson;
      },
      subscribe(module, event, listener) {
        active();
        let events = listeners.get(module);
        if (!events) listeners.set(module, events = new Map());
        let callbacks = events.get(event);
        if (!callbacks) events.set(event, callbacks = new Set());
        const entry = { listener };
        callbacks.add(entry);
        let removed = false;
        return { remove() {
          if (removed) return;
          removed = true;
          callbacks.delete(entry);
          if (!callbacks.size) events.delete(event);
          if (!events.size) listeners.delete(module);
        } };
      },
      dispose,
    };
  } catch (error) {
    dispose();
    throw error;
  }
}

/** Await before dynamically importing nativeApi/main, whose native facades bind during module evaluation. */
export async function initializeWebNativeBridge(options: WebNativeBridgeOptions): Promise<EventSubscription> {
  const transport = await createMojoTransport(options);
  try { return installNativeTransport(transport); }
  catch (error) { transport.dispose?.(); throw error; }
}
